        case 0xee602ee8:  numBytes = 5654; return GR_MATCH_Button_ON_png;
        case 0x012a3483:  numBytes = 10522; return GrayKnob_png;
        case 0xbbb64aad:  numBytes = 4734; return GRCurve_Embos_png;
