        case 0x004b12d2:  numBytes = 3814; return GRHistory_Embos_png;
        case 0x7e3d18bc:  numBytes = 3862; return INOUT_Meter_Embos_png;
        case 0x86efc528:  numBytes = 3020; return KnobHighlight_png;
        case 0xc01378a5:  numBytes = 7070; return KnobReflectOver_png;
        case 0xe3efce1b:  numBytes = 2147742; return Mock_v2_png;
        case 0x8468e7b4:  numBytes = 1937971; return NoMeterCurtain_png;
        case 0xbfe947bf:  numBytes = 9402; return OPTO_Button_png;
        case 0xb1ff5e73:  numBytes = 7639; return OPTO_Button_ON_png;
